import java.util.*

fun isVowel(c: Char): Boolean {
    return c == 'A' || c == 'E' || c == 'O' || c == 'U' || c == 'Y' || c == 'I'
}

fun main() {
    val scanner = Scanner(System.`in`)
    var str = scanner.nextLine()
    str = " $str "
    var jumpSize = 1
    var pos = 0
    var next: Int
    do {
        next = pos + 1
        while (str[next] != ' ' && !isVowel(str[next])) {
            next++
        }
        jumpSize = Math.max(jumpSize, next - pos)
        pos = next
    } while (str[pos] != ' ')
    println(jumpSize)
}
